'@

$tempPatch = Join-Path $env:TEMP "legaltech-v37-connector-reliability-compat.patch"
[IO.File]::WriteAllBytes($tempPatch, [Convert]::FromBase64String(($patchBase64 -replace "\s","")))

Write-Host "Using embedded compatibility patch." -ForegroundColor Cyan

git apply --check "$tempPatch" 2>$null
$canApply = ($LASTEXITCODE -eq 0)

if ($canApply) {
    Write-Host "Applying compatibility patch..." -ForegroundColor Yellow
    git apply "$tempPatch"
    if ($LASTEXITCODE -ne 0) { Fail "Patch application failed." }
} else {
    git apply --reverse --check "$tempPatch" 2>$null
    $alreadyApplied = ($LASTEXITCODE -eq 0)
    if ($alreadyApplied) {
        Write-Host "Compatibility patch is already applied." -ForegroundColor Green
    } else {
        Fail "Compatibility patch does not match this repository state."
    }
}

Write-Host ""
Write-Host "Changed files:" -ForegroundColor Cyan
git status --short | Out-Host

Write-Host ""
Write-Host "Running platform tests..." -ForegroundColor Cyan
Push-Location ".\40_PLATFORM_FOUNDATION_BUILD"
npm test
$platformExit = $LASTEXITCODE
Pop-Location
if ($platformExit -ne 0) { Fail "Platform tests failed." }

Write-Host ""
Write-Host "Running security tests..." -ForegroundColor Cyan
python ".\32_SECURITY_REGRESSION_AUTOMATION\run_security_policy_tests.py"
if ($LASTEXITCODE -ne 0) { Fail "Security tests failed." }

Write-Host ""
Write-Host "Regenerating Claude catalog..." -ForegroundColor Cyan
python ".\36_CLAUDE_KNOWLEDGE_ARCHITECTURE\scripts\regenerate_catalog.py"
if ($LASTEXITCODE -ne 0) { Fail "Catalog regeneration failed." }

Write-Host ""
Write-Host "Running Claude knowledge lint..." -ForegroundColor Cyan
python ".\36_CLAUDE_KNOWLEDGE_ARCHITECTURE\scripts\knowledge_lint.py"
if ($LASTEXITCODE -ne 0) { Fail "Knowledge lint failed." }

git add -A

Write-Host ""
Write-Host "Staged changes:" -ForegroundColor Cyan
git diff --cached --stat | Out-Host

git diff --cached --quiet
$noStagedChanges = ($LASTEXITCODE -eq 0)

if (-not $noStagedChanges) {
    git commit -m "feat: add connector reliability harness" | Out-Host
    if ($LASTEXITCODE -ne 0) { Fail "Commit failed." }
} else {
    Write-Host "No new staged changes; checking whether commit already exists." -ForegroundColor Yellow
}

$ahead = git log origin/main..HEAD --oneline
Write-Host ""
Write-Host "Commits ahead of origin/main:" -ForegroundColor Cyan
$ahead | Out-Host

if (-not $ahead) {
    Fail "No commit exists ahead of origin/main."
}

Write-Host ""
Write-Host "Pushing feature branch..." -ForegroundColor Cyan
git push -u origin feat/connector-reliability | Out-Host
if ($LASTEXITCODE -ne 0) { Fail "Push failed." }

$existingPr = gh pr list --head feat/connector-reliability --json url --jq '.[0].url'

if ($existingPr) {
    Write-Host ""
    Write-Host "PR already exists: $existingPr" -ForegroundColor Green
    gh pr view "$existingPr" --web
} else {
    Write-Host ""
    Write-Host "Creating pull request..." -ForegroundColor Cyan
    gh pr create --base main --head feat/connector-reliability --title "feat: add connector reliability harness" --body "Adds connector reliability operations, webhook deduplication, retry/dead-letter visibility, recovery controls, integration health telemetry, and Git-safe Claude catalog handling."
    if ($LASTEXITCODE -ne 0) { Fail "PR creation failed." }
}

Remove-Item $tempPatch -ErrorAction SilentlyContinue

Write-Host ""
Write-Host "SUCCESS: 33-test connector reliability build is committed, pushed, and ready for PR review." -ForegroundColor Green
